mapper.select:

where status = 1

    and map_type = #{mapType}


    and supplier_id in
    #{sid}


    and (supplier_account_id = 0 or supplier_account_id in
    #{aid}
    )

order by supplier_account_id desc

select m.id, m.supplier_id, s.name as supplier_name, m.supplier_account_id, a.account_name, m.map_type, m.upstream_key, m.upstream_variant, m.target_id, cu.name as customer_name, m.target_code, mp.name as model_name, mp.no as model_no, m.status, m.remark, m.creator, m.create_time, m.update_time from crm_gateway_pull_map m left join crm_supplier s on m.supplier_id = s.id left join crm_supplier_account a on m.supplier_account_id = a.id left join crm_customer cu on m.target_id = cu.id left join crm_model_product mp on m.target_code = mp.product_code and mp.deleted = 0
and m.supplier_id = #{supplierId} and m.supplier_account_id = #{supplierAccountId} and m.map_type = #{mapType}
and m.upstream_key like concat('%', #{upstreamKey}, '%')
and m.status = #{status}
order by m.supplier_id, m.map_type, m.supplier_account_id, m.id

mapper.update:
update crm_gateway_pull_map
supplier_id = #{supplierId}, supplier_account_id = #{supplierAccountId}, map_type = #{mapType}, upstream_key = #{upstreamKey}, upstream_variant = #{upstreamVariant}, target_id = #{targetId}, target_code = #{targetCode}, status = #{status}, remark = #{remark}, update_time = sysdate(),
where id = #{id}

mapper.select:
select count(1) from crm_gateway_pull_map
where supplier_id = #{map.supplierId}
  and supplier_account_id = ifnull(#{map.supplierAccountId}, 0)
  and map_type = #{map.mapType}
  and upstream_key = ifnull(#{map.upstreamKey}, '')
  and upstream_variant = ifnull(#{map.upstreamVariant}, '')

    and id != #{excludeId}
